:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #e0e0f0;
  --accent: #7c5cbf;
  --accent-hover: #9b7fd4;
  --border: #3e3e5e;
  --happy: #f9d71c;
  --sad: #5c9edb;
  --angry: #e05a5a;
  --tired: #a0a0b0;
  --excited: #f08c3a;
  --radius: 10px;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 2rem 1rem;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 600px;
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 2rem;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.75rem;
  margin: 0 0 0.25rem;
  text-align: center;
}

.subtitle {
  text-align: center;
  margin: 0 0 1.5rem;
  opacity: 0.8;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

/* Mood picker */
.mood-picker {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.mood-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.4rem;
  padding: 0.75rem 0.5rem;
  min-width: 80px;
  background: transparent;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 1rem;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s, transform 0.1s;
}

.mood-btn:hover {
  border-color: var(--accent-hover);
  background: rgba(124, 92, 191, 0.15);
}

.mood-btn:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

.mood-btn:active {
  transform: scale(0.95);
}

.mood-btn[aria-checked="true"] {
  border-color: var(--accent);
  background: rgba(124, 92, 191, 0.25);
  box-shadow: 0 0 0 2px var(--accent);
}

.mood-label {
  font-size: 0.9rem;
}

/* Pixel faces via CSS box-shadow art */
.pixel-face {
  width: 32px;
  height: 32px;
  position: relative;
  image-rendering: pixelated;
}

.pixel-face::before {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow:
    8px 4px 0 currentColor, 20px 4px 0 currentColor,
    4px 8px 0 currentColor, 12px 8px 0 currentColor, 16px 8px 0 currentColor, 24px 8px 0 currentColor,
    4px 12px 0 currentColor, 24px 12px 0 currentColor,
    4px 16px 0 currentColor, 24px 16px 0 currentColor,
    8px 20px 0 currentColor, 20px 20px 0 currentColor,
    12px 24px 0 currentColor, 16px 24px 0 currentColor;
}

/* Mouth variations */
.pixel-face.happy::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow: 12px 20px 0 currentColor, 16px 20px 0 currentColor, 8px 16px 0 currentColor, 20px 16px 0 currentColor;
}

.pixel-face.sad::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow: 12px 16px 0 currentColor, 16px 16px 0 currentColor, 8px 20px 0 currentColor, 20px 20px 0 currentColor;
}

.pixel-face.angry::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow: 12px 20px 0 currentColor, 16px 20px 0 currentColor, 8px 16px 0 currentColor, 20px 16px 0 currentColor, 8px 12px 0 currentColor, 20px 12px 0 currentColor;
}

.pixel-face.tired::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow: 12px 16px 0 currentColor, 16px 16px 0 currentColor;
}

.pixel-face.excited::after {
  content: '';
  position: absolute;
  width: 4px;
  height: 4px;
  background: currentColor;
  box-shadow: 12px 16px 0 currentColor, 16px 16px 0 currentColor, 8px 20px 0 currentColor, 20px 20px 0 currentColor, 12px 24px 0 currentColor, 16px 24px 0 currentColor;
}

.pixel-face.happy { color: var(--happy); }
.pixel-face.sad { color: var(--sad); }
.pixel-face.angry { color: var(--angry); }
.pixel-face.tired { color: var(--tired); }
.pixel-face.excited { color: var(--excited); }

/* Note area */
.note-area {
  margin-bottom: 1rem;
}

.note-area label {
  display: block;
  margin-bottom: 0.4rem;
  font-weight: 600;
}

#note-input {
  width: 100%;
  padding: 0.75rem;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  resize: vertical;
}

#note-input:focus-visible {
  outline: 3px solid var(--accent-hover);
  outline-offset: 2px;
}

/* Primary button */
.primary-btn {
  display: block;
  width: 100%;
  padding: 0.9rem;
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  margin-bottom: 2rem;
}

.primary-btn:hover { background: var(--accent-hover); }
.primary-btn:focus-visible { outline: 3px solid var(--accent-hover); outline-offset: 2px; }
.primary-btn:active { transform: scale(0.98); }

/* Summary */
.summary {
  margin-bottom: 2rem;
}

.summary h2, .entries-list + h2, h2 {
  font-size: 1.2rem;
  margin: 0 0 0.75rem;
  border-bottom: 2px solid var(--border);
  padding-bottom: 0.4rem;
}

.counts-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.counts-list li {
  background: var(--bg);
  padding: 0.4rem 0.8rem;
  border-radius: 20px;
  font-size: 0.95rem;
  border: 1px solid var(--border);
}

/* Entries list */
.entries-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  max-height: 400px;
  overflow-y: auto;
}

.entry {
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
  display: flex;
  gap: 0.75rem;
  align-items: flex-start;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-4px); }
  to { opacity: 1; transform: translateY(0); }
}

.entry .pixel-face {
  flex-shrink: 0;
  margin-top: 2px;
}

.entry-content {
  flex: 1;
  min-width: 0;
}

.entry-date {
  font-size: 0.85rem;
  opacity: 0.7;
  display: block;
}

.entry-note {
  margin: 0.2rem 0 0;
  word-wrap: break-word;
}

.empty-msg {
  opacity: 0.6;
  font-style: italic;
  text-align: center;
  padding: 1rem 0;
}

/* Responsive */
@media (max-width: 420px) {
  .card { padding: 1.25rem; }
  .mood-btn { min-width: 60px; padding: 0.5rem 0.3rem; }
  .mood-label { font-size: 0.8rem; }
  h1 { font-size: 1.4rem; }
}

(function () {
  'use strict';

  const MOODS = ['happy', 'sad', 'angry', 'tired', 'excited'];
  const STORAGE_KEY = 'pixel-mood-journal-entries';

  const moodButtons = Array.from(document.querySelectorAll('.mood-btn'));
  const noteInput = document.getElementById('note-input');
  const addBtn = document.getElementById('add-entry');
  const entriesList = document.getElementById('entries-list');
  const countsList = document.getElementById('mood-counts');

  let selectedMood = null;
  let entries = loadEntries();

  function loadEntries() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch (e) {
      return [];
    }
  }

  function saveEntries() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(entries));
    } catch (e) {
      /* storage unavailable */
    }
  }

  function selectMood(mood) {
    selectedMood = mood;
    moodButtons.forEach(function (btn) {
      const isSelected = btn.dataset.mood === mood;
      btn.setAttribute('aria-checked', isSelected ? 'true' : 'false');
    });
  }

  function createFace(mood) {
    const face = document.createElement('span');
    face.className = 'pixel-face ' + mood;
    face.setAttribute('aria-hidden', 'true');
    return face;
  }

  function formatDate(iso) {
    const d = new Date(iso);
    return d.toLocaleDateString(undefined, {
      year: 'numeric', month: 'short', day: 'numeric'
    });
  }

  function renderEntries() {
    entriesList.innerHTML = '';
    if (entries.length === 0) {
      const li = document.createElement('li');
      li.className = 'empty-msg';
      li.textContent = 'No entries yet. Pick a mood and add one!';
      entriesList.appendChild(li);
      return;
    }

    const sorted = entries.slice().sort(function (a, b) {
      return new Date(b.date) - new Date(a.date) || b.id - a.id;
    });

    sorted.forEach(function (entry) {
      const li = document.createElement('li');
      li.className = 'entry';

      li.appendChild(createFace(entry.mood));

      const content = document.createElement('div');
      content.className = 'entry-content';

      const dateSpan = document.createElement('span');
      dateSpan.className = 'entry-date';
      dateSpan.textContent = formatDate(entry.date);
      content.appendChild(dateSpan);

      if (entry.note) {
        const noteP = document.createElement('p');
        noteP.className = 'entry-note';
        noteP.textContent = entry.note;
        content.appendChild(noteP);
      }

      li.appendChild(content);
      entriesList.appendChild(li);
    });
  }

  function renderCounts() {
    countsList.innerHTML = '';
    const counts = {};
    MOODS.forEach(function (m) { counts[m] = 0; });
    entries.forEach(function (e) {
      if (counts[e.mood] !== undefined) counts[e.mood]++;
    });

    MOODS.forEach(function (mood) {
      const li = document.createElement('li');
      li.textContent = mood.charAt(0).toUpperCase() + mood.slice(1) + ': ' + counts[mood];
      countsList.appendChild(li);
    });
  }

  function addEntry() {
    if (!selectedMood) {
      addBtn.textContent = 'Pick a mood first!';
      addBtn.classList.add('error');
      setTimeout(function () {
        addBtn.textContent = 'Add Entry';
        addBtn.classList.remove('error');
      }, 1500);
      return;
    }

    const note = noteInput.value.trim();
    const now = new Date();
    entries.push({
      id: Date.now(),
      mood: selectedMood,
      note: note,
      date: now.toISOString()
    });

    saveEntries();
    noteInput.value = '';
    renderEntries();
    renderCounts();

    addBtn.textContent = 'Added!';
    setTimeout(function () {
      addBtn.textContent = 'Add Entry';
    }, 1000);
  }

  // Event listeners
  moodButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      selectMood(btn.dataset.mood);
    });
  });

  addBtn.addEventListener('click', addEntry);

  noteInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      addEntry();
    }
  });

  // Initial render
  renderEntries();
  renderCounts();
})();
